"use strict";(self.webpackChunkpaulus_seo=self.webpackChunkpaulus_seo||[]).push([[130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"website-renewal","metadata":{"permalink":"/blog/website-renewal","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-01-17-website-renewal.md","source":"@site/blog/2026-01-17-website-renewal.md","title":"\uc6f9\uc0ac\uc774\ud2b8 \ub9ac\ub274\uc5bc \uc791\uc5c5 \uae30\ub85d","description":"\uc548\ub155\ud558\uc138\uc694! \uc624\ub298\uc740 \uc81c \uac1c\uc778 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc6f9\uc0ac\uc774\ud2b8\uc5d0 \ub300\ud55c \ub9ac\ub274\uc5bc \uc791\uc5c5 \uae30\ub85d\uc744 \uacf5\uc720\ud558\ub824 \ud569\ub2c8\ub2e4.","date":"2026-01-17T00:00:00.000Z","tags":[{"inline":false,"label":"Docusaurus","permalink":"/blog/tags/docusaurus","description":"Docusaurus tag description"},{"inline":true,"label":"renewal","permalink":"/blog/tags/renewal"},{"inline":true,"label":"portfolio","permalink":"/blog/tags/portfolio"},{"inline":true,"label":"web-dev","permalink":"/blog/tags/web-dev"}],"readingTime":1.02,"hasTruncateMarker":true,"authors":[{"name":"Paul Seo","title":"Robotics Software Engineer, Hyundai-WIA","url":"http://linkedin.com/in/paulusseo/","page":{"permalink":"/blog/authors/paulus-seo"},"socials":{"github":"https://github.com/paulus-seo","linkedin":"https://www.linkedin.com/in/paulusseo/"},"imageURL":"https://github.com/paulus-seo.png","key":"paulus-seo"}],"frontMatter":{"slug":"website-renewal","title":"\uc6f9\uc0ac\uc774\ud2b8 \ub9ac\ub274\uc5bc \uc791\uc5c5 \uae30\ub85d","authors":["paulus-seo"],"tags":["docusaurus","renewal","portfolio","web-dev"]},"unlisted":false},"content":"\uc548\ub155\ud558\uc138\uc694! \uc624\ub298\uc740 \uc81c \uac1c\uc778 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc6f9\uc0ac\uc774\ud2b8\uc5d0 \ub300\ud55c \ub9ac\ub274\uc5bc \uc791\uc5c5 \uae30\ub85d\uc744 \uacf5\uc720\ud558\ub824 \ud569\ub2c8\ub2e4.\\nDocusaurus \uae30\ubc18\uc73c\ub85c \uad6c\ucd95\ub41c \uc774 \uc6f9\uc0ac\uc774\ud2b8\ub294 \ubc29\ubb38\uc790\ub4e4\uc5d0\uac8c \uc800\uc758 \uacbd\ud5d8\uacfc \ud504\ub85c\uc81d\ud2b8\ub97c \ubcf4\ub2e4 \ud6a8\uacfc\uc801\uc73c\ub85c \uc804\ub2ec\ud558\uae30 \uc704\ud574 \uc5ec\ub7ec \ud398\uc774\uc9c0\uac00 \uac1c\uc120\ub418\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n**\uc8fc\uc694 \ub9ac\ub274\uc5bc \ub0b4\uc6a9:**\\n\\n1.  **Awards \ud398\uc774\uc9c0 \ucd94\uac00**: \uc800\uc758 \uc218\uc0c1 \uc774\ub825\uc744 \ud55c\ub208\uc5d0 \ubcfc \uc218 \uc788\ub294 `Awards` \ud398\uc774\uc9c0\ub97c \uc0c8\ub85c \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \uae30\uc874 \ud504\ub85c\uc81d\ud2b8 \ud398\uc774\uc9c0\uc640 \uc720\uc0ac\ud55c \uce74\ub4dc\ud615 \ub808\uc774\uc544\uc6c3\uc73c\ub85c \uc77c\uad00\uc131\uc744 \uc720\uc9c0\ud588\uc2b5\ub2c8\ub2e4.\\n2.  **Projects \ud398\uc774\uc9c0 \uac1c\uc120**: \uae30\uc874\uc758 \uac04\ub2e8\ud55c `Projects` \ud398\uc774\uc9c0\ub97c \ub2e4\uc591\ud55c \uc800\uc758 \ud504\ub85c\uc81d\ud2b8\ub4e4\uc744 \uce74\ub4dc \ud615\ud0dc\ub85c \ubcf4\uc5ec\uc8fc\ub294 \uac24\ub7ec\ub9ac \ud615\ud0dc\ub85c \uc5c5\ub370\uc774\ud2b8\ud588\uc2b5\ub2c8\ub2e4. \uac01 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ub300\ud55c \uc124\uba85\uacfc \uc774\ubbf8\uc9c0\ub97c \ud1b5\ud574 \uc27d\uac8c \ub0b4\uc6a9\uc744 \ud30c\uc545\ud560 \uc218 \uc788\ub3c4\ub85d \ud588\uc2b5\ub2c8\ub2e4.\\n3.  **About \ud398\uc774\uc9c0 \ud0c0\uc784\ub77c\uc778 \uac1c\ud3b8**: \uac00\uc7a5 \ud070 \ubcc0\ud654\ub294 `About` \ud398\uc774\uc9c0\uc785\ub2c8\ub2e4. \uc800\uc758 \ud559\ub825 \ubc0f \uacbd\ub825 \uc0ac\ud56d\uc744 LinkedIn \uc2a4\ud0c0\uc77c\uc758 \ud0c0\uc784\ub77c\uc778\uc73c\ub85c \uc7ac\uad6c\uc131\ud588\uc2b5\ub2c8\ub2e4.\\n    *   **\uacc4\uce35\uc801 \uad6c\uc870**: \uac01 \uae30\uad00/\ud68c\uc0ac\ubcc4\ub85c \uadf8\ub8f9\ud654\ud558\uc5ec, \uadf8\ub8f9 \ud5e4\ub354(\ub300\ud45c \ub85c\uace0 \ubc0f \uc774\ub984) \uc544\ub798\uc5d0 \ud574\ub2f9 \uae30\uad00/\ud68c\uc0ac\uc5d0\uc11c\uc758 \ud65c\ub3d9\ub4e4\uc744 \uc2dc\uac04\uc21c\uc73c\ub85c \ub098\uc5f4\ud588\uc2b5\ub2c8\ub2e4.\\n    *   **\ub300\ud45c \ub85c\uace0 \ubc0f \uc11c\ube0c \ub85c\uace0 \ubd84\ub9ac**: \uac01 \uadf8\ub8f9\uc740 \ub300\ud45c \ub85c\uace0\ub97c \uac00\uc9c0\uba70, \uadf8\ub8f9 \ub0b4 \uac1c\ubcc4 \ud65c\ub3d9(\ud559\uc704, \uc9c1\ucc45 \ub4f1) \ub610\ud55c \ubcc4\ub3c4\uc758 \ub85c\uace0\ub97c \uac00\uc9c8 \uc218 \uc788\ub3c4\ub85d \ud558\uc5ec \uc2dc\uc778\uc131\uc744 \ub192\uc600\uc2b5\ub2c8\ub2e4.\\n    *   **\ud638\ubc84 \ud6a8\uacfc**: \uac01 `groupItem` \uce74\ub4dc\uc5d0 \ub9c8\uc6b0\uc2a4\ub97c \uc62c\ub9ac\uba74 \uc0b4\uc9dd \ud280\uc5b4\ub098\uc624\ub294 \ub4ef\ud55c \uc2dc\uac01\uc801 \ud6a8\uacfc\ub97c \ucd94\uac00\ud558\uc5ec \uc778\ud130\ub799\ud2f0\ube0c\ud55c \uacbd\ud5d8\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n    *   **\ub514\uc790\uc778 \uac1c\uc120**: \ub85c\uace0 \ud14c\ub450\ub9ac \uc644\ud654 \ubc0f `groupHeader`\uc640 \uccab \ubc88\uc9f8 `groupItem` \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc870\uc808\ud558\uc5ec \uc804\uccb4\uc801\uc778 \ub514\uc790\uc778\uc774 \ub354\uc6b1 \uc790\uc5f0\uc2a4\ub7fd\uace0 \uae54\ub054\ud558\uac8c \ubcf4\uc774\ub3c4\ub85d \uac1c\uc120\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ubc88 \ub9ac\ub274\uc5bc\uc744 \ud1b5\ud574 \uc800\uc758 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uc6f9\uc0ac\uc774\ud2b8\uac00 \ub354\uc6b1 \uc804\ubb38\uc801\uc774\uace0 \uc0ac\uc6a9\uc790 \uce5c\ud654\uc801\uc73c\ub85c \ubc14\ub00c\uc5c8\uae30\ub97c \uae30\ub300\ud569\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub3c4 \uafb8\uc900\ud788 \ub0b4\uc6a9\uc744 \uc5c5\ub370\uc774\ud2b8\ud558\uace0 \ubc1c\uc804\uc2dc\ucf1c \ub098\uac00\uaca0\uc2b5\ub2c8\ub2e4.\\n\uac10\uc0ac\ud569\ub2c8\ub2e4!"}]}}')}}]);